namespace ToneCustoms.ShellStudio.Editor;
public sealed class UndoRedoManager { sealed record Command(Action Undo,Action Redo);readonly Stack<Command> undo=[];readonly Stack<Command> redo=[];public bool CanUndo=>undo.Count>0;public bool CanRedo=>redo.Count>0;public void Execute(Action redoAction,Action undoAction){redoAction();undo.Push(new(undoAction,redoAction));redo.Clear();}public void Undo(){if(!undo.TryPop(out var c))return;c.Undo();redo.Push(c);}public void Redo(){if(!redo.TryPop(out var c))return;c.Redo();undo.Push(c);}public void Clear(){undo.Clear();redo.Clear();} }
